"""Triton implementation of the functional ``aten::_foreach_copy``.

``run(self, src, non_blocking=False) -> list[Tensor]``

For every pair ``(self[i], src[i])`` a new output tensor is allocated with
``self[i]``'s dtype/shape/strides (``empty_like`` semantics, matching ATen's
composite implementation) and ``src[i]`` is copied into it with ATen
``copy_`` semantics:

* no dtype promotion -- the source value is cast directly to the destination
  dtype (``static_cast`` behaviour: truncation for float -> int, low-bit
  truncation for integer narrowing, round-to-nearest for float -> float),
* ``src[i]`` is broadcast to the destination's logical index space,
* same-dtype pairs are bit exact (copied through an integer view of identical
  element width, which also keeps ``bool`` off Triton's ``int1`` pointer path).
"""

import torch
import triton
import triton.language as tl

_TL_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
    torch.int8: tl.int8,
    torch.int16: tl.int16,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
    torch.uint8: tl.uint8,
    torch.bool: tl.int1,
}

_INT32_MAX = 2**31 - 1
_MAX_RANK = 8
_MAX_FUSED = 8
# Fusing a call's pairs into a single launch only pays while the launch floor
# (or the per-launch pipeline fill) is a measurable share of the call.  Above
# this much total traffic the pairs are streamed by the per-pair kernel, which
# measured faster than a merged launch for the 8 x 2 GiB class.
_FUSE_MAX_BYTES = 2 << 30


