# ---------------------------------------------------------------------------


@triton.jit
def _copy_flat_kernel(
    src_ptr,
    dst_ptr,
    n,
    BLOCK: tl.constexpr,
    DST_DT: tl.constexpr,
    DST_BOOL: tl.constexpr,
    I64: tl.constexpr,
):
    """Dense, equal-element-count copy (both sides contiguous)."""
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    if I64:
        offs = offs.to(tl.int64)
    mask = offs < n
    v = tl.load(src_ptr + offs, mask=mask)
    if DST_BOOL:
        v = v != 0
    tl.store(dst_ptr + offs, v.to(DST_DT), mask=mask)


@triton.jit
def _copy_tile(
    src_ptr,
    dst_ptr,
    n,
    off,
    BLOCK: tl.constexpr,
    DST_DT: tl.constexpr,
    DST_BOOL: tl.constexpr,
):
    offs = off + tl.arange(0, BLOCK)
    mask = offs < n
    v = tl.load(src_ptr + offs, mask=mask)
    if DST_BOOL:
        v = v != 0
    tl.store(dst_ptr + offs, v.to(DST_DT), mask=mask)


@triton.jit
def _copy_batch_kernel(
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    n0,
    n1,
    n2,
    n3,
    n4,
    n5,
    n6,
    n7,
    BLOCK: tl.constexpr,
    DST_DT: tl.constexpr,
    DST_BOOL: tl.constexpr,
    NT: tl.constexpr,
    I64: tl.constexpr,
):
    """Up to eight dense pairs in one launch, branch-free.

    Grid is ``(cdiv(max_n, BLOCK),)``: every program copies the same tile index
    of *all* real pairs, so there is no pair-selection control flow -- the
    round-3 profile showed the ``scf.if`` chain paying 8 set_flag / 8 wait_flag
    + PIPE_ALL barrier / 8 comparisons per program and a per-program cost that
    scaled with program count.  Each pair keeps its own ``n_i`` mask; unused
    slots are padded with ``n=0`` and statically eliminated by ``NT``.
    """
    off = tl.program_id(0) * BLOCK
    if I64:
        off = off.to(tl.int64)
    if NT > 0:
        _copy_tile(s0, d0, n0, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 1:
        _copy_tile(s1, d1, n1, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 2:
        _copy_tile(s2, d2, n2, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 3:
        _copy_tile(s3, d3, n3, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 4:
        _copy_tile(s4, d4, n4, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 5:
        _copy_tile(s5, d5, n5, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 6:
        _copy_tile(s6, d6, n6, off, BLOCK, DST_DT, DST_BOOL)
    if NT > 7:
        _copy_tile(s7, d7, n7, off, BLOCK, DST_DT, DST_BOOL)


@triton.jit
def _copy_strided_kernel(
    src_ptr,
    dst_ptr,
    n,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    u0,
    u1,
    u2,
    u3,
    u4,
    u5,
    u6,
    u7,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    BLOCK: tl.constexpr,
    DST_DT: tl.constexpr,
    DST_BOOL: tl.constexpr,
):
    """Strided / broadcast copy.

    ``d*`` are the (collapsed) destination sizes innermost-first, ``u*`` the
    destination strides and ``t*`` the effective source strides (``0`` on
    broadcast dimensions).  Slots past the real rank are ``d=1, u=0, t=0``.
    """
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    idx = offs
    so = tl.zeros([BLOCK], tl.int32)
    do = tl.zeros([BLOCK], tl.int32)
    i = idx % d0
    idx = idx // d0
    so += i * t0
    do += i * u0
    i = idx % d1
    idx = idx // d1
    so += i * t1
    do += i * u1
    i = idx % d2
    idx = idx // d2
    so += i * t2
    do += i * u2
    i = idx % d3
    idx = idx // d3
    so += i * t3
    do += i * u3
    i = idx % d4
    idx = idx // d4
    so += i * t4
    do += i * u4
    i = idx % d5
    idx = idx // d5
    so += i * t5
    do += i * u5
    i = idx % d6
    idx = idx // d6
    so += i * t6
    do += i * u6
    i = idx % d7
    idx = idx // d7
    so += i * t7
    do += i * u7
    v = tl.load(src_ptr + so, mask=mask)
    if DST_BOOL:
        v = v != 0
    tl.store(dst_ptr + do, v.to(DST_DT), mask=mask)


# ---------------------------------------------------------------------------
# per-pair argument conditioning
# ---------------------------------------------------------------------------


def _tl_dtype(dtype):
    out = _TL_DTYPE.get(dtype)
    if out is None:
        raise NotImplementedError(f"_foreach_copy does not support dtype {dtype}")
    return out


def _bool_view(tensor):
    """Same-width integer view of a bool tensor (avoids ``tl.int1`` pointers)."""
    try:
        return tensor.view(torch.int8), True
    except RuntimeError:
        return tensor, False


def _pair_args(dst, src):
    """(src_arg, dst_arg, dst_tl_dtype, dst_is_bool) for one pair."""
    sdt = src.dtype
    ddt = dst.dtype
    if sdt == ddt:
        if ddt == torch.bool:
            s, ok_s = _bool_view(src)
            d, ok_d = _bool_view(dst)
            if ok_s and ok_d:
                return s, d, tl.int8, False
            return s, d, tl.int1, False
        if ddt.is_complex:
            real = torch.float32 if ddt == torch.complex64 else torch.float64
            return src.view(real), dst.view(real), _tl_dtype(real), False
        return src, dst, _tl_dtype(ddt), False

    if sdt.is_complex or ddt.is_complex:
        raise NotImplementedError(
            "_foreach_copy cannot convert between complex and other dtypes"
        )

    dst_bool = ddt == torch.bool
    if dst_bool:
        d, ok_d = _bool_view(dst)
        dst_dt = tl.int8 if ok_d else tl.int1
    else:
        d = dst
        dst_dt = _tl_dtype(ddt)

    if sdt == torch.bool:
        s, _ = _bool_view(src)
    else:
        s = src
        _tl_dtype(sdt)
    return s, d, dst_dt, dst_bool


# ---------------------------------------------------------------------------
# layout helpers
# ---------------------------------------------------------------------------


def _block_for(n):
    if n <= 2048:
        return 256
    if n <= 32768:
        return 1024
    if n <= 262144:
        return 4096
    if n <= (1 << 28):
        return 8192
    # Multi-hundred-MB tensors: a longer burst per DMA instruction, which
    # measured ~13% faster at 32 KiB than at 16 KiB on this target.
    return 32768


def _collapse(dst, src):
    """Collapse to (sizes, dst_strides, src_strides), innermost dim first.

    Returns ``None`` when ``src`` cannot be broadcast onto ``dst``.
    """
    dshape = dst.shape
    dstride = dst.stride()
    rank = len(dshape)
    srank = src.dim()
    if srank > rank:
        return None
    full_ssize = [1] * rank
    full_sstride = [0] * rank
    sshape = src.shape
    sstride = src.stride()
    off = rank - srank
    for i in range(srank):
        d = off + i
        size = sshape[i]
        if size != 1 and size != dshape[d]:
            return None
        full_ssize[d] = size
        full_sstride[d] = sstride[i]

    dims = [
        (dshape[d], dstride[d], full_ssize[d], full_sstride[d])
        for d in range(rank)
        if dshape[d] != 1
    ]
    if not dims:
        dims = [(1, 1, 1, 0)]

    merged = []
    for dsz, dstr, ssz, sstr in dims:
        if merged:
            psz, pstr, pssz, psstr = merged[-1]
            if pstr == dstr * dsz and psstr == sstr * ssz:
                merged[-1] = (psz * dsz, pstr, pssz * ssz, psstr)
                continue
        merged.append((dsz, dstr, ssz, sstr))

    merged.reverse()  # innermost first
    sizes = [m[0] for m in merged]
    u = [m[1] for m in merged]
    t = [m[3] for m in merged]
    return sizes, u, t


def _pad8(values):
    out = list(values)
    while len(out) < _MAX_RANK:
        out.append(0)
    return out


def _pad8_sizes(values):
    out = list(values)
    while len(out) < _MAX_RANK:
        out.append(1)
    return out


# ---------------------------------------------------------------------------
# per-pair launches
# ---------------------------------------------------------------------------


def _launch_flat(src_arg, dst_arg, n, dst_dt, dst_bool):
    block = _block_for(n)
    # Keep one tile plus its ping-pong partner inside the per-core UB: a 64 KiB
    # tile at two stages is the largest that fits for 2-byte elements, so wider
    # dtypes get proportionally smaller tiles.
    esz = src_arg.element_size()
    if dst_arg.element_size() > esz:
        esz = dst_arg.element_size()
    cap = 65536 // esz if esz else 8192
    if block > cap:
        block = cap
    if block < 64:
        block = 64
    grid = (triton.cdiv(n, block),)
    _copy_flat_kernel[grid](
        src_arg,
        dst_arg,
        n,
        BLOCK=block,
        DST_DT=dst_dt,
        DST_BOOL=dst_bool,
        I64=n > _INT32_MAX,
    )


def _launch_batch(items, dst_dt, dst_bool):
    """One launch for ``len(items)`` dense pairs sharing dtype width."""
    nt = len(items)
    srcs = [it[0] for it in items]
    dsts = [it[1] for it in items]
    ns = [it[2] for it in items]
    pad = _MAX_FUSED - nt
    if pad:
        srcs.extend([srcs[-1]] * pad)
        dsts.extend([dsts[-1]] * pad)
        ns.extend([0] * pad)
    max_n = max(ns)
    esz = max(srcs[0].element_size(), dsts[0].element_size())
    block = _batch_block(max_n, esz)
    grid = (triton.cdiv(max_n, block),)
    _copy_batch_kernel[grid](
        *srcs,
        *dsts,
        *ns,
        BLOCK=block,
        DST_DT=dst_dt,
        DST_BOOL=dst_bool,
        NT=nt,
        I64=max_n > _INT32_MAX,
    )


def _batch_block(n, esz):
    """Tile size for the fused launch.

    The fused body keeps ``NT`` destination tiles live at once, so the tile has
    to stay small enough that ``8 pairs x 2 pipeline stages x BLOCK * itemsize``
    fits comfortably in the per-core UB; the streaming-friendly size from
    ``_block_for`` is used when it already satisfies that bound.
    """
    block = _block_for(n)
    cap = 8192 // esz if esz else 1024
    if block > cap:
        block = cap
    return block if block >= 64 else 64


def _group_bytes(items):
    total = 0
    for src_arg, dst_arg, n, _ in items:
        total += n * (src_arg.element_size() + dst_arg.element_size())
    return total


def _launch_strided(src_arg, dst_arg, dst, src, dst_dt, dst_bool):
    n = dst.numel()
    coll = _collapse(dst, src)
    if coll is None or len(coll[0]) > _MAX_RANK:
        return False
    sizes, u, t = coll
    # The strided body keeps several full-width int32 offset vectors live, so it
    # stays with the small streaming tile regardless of numel.
    block = _block_for(n)
    if block > 8192:
        block = 8192
    grid = (triton.cdiv(n, block),)
    _copy_strided_kernel[grid](
        src_arg,
        dst_arg,
        n,
        *_pad8_sizes(sizes),
        *_pad8(u),
        *_pad8(t),
        BLOCK=block,
        DST_DT=dst_dt,
        DST_BOOL=dst_bool,
    )
    return True


def _copy_pair(dst, src):
    n = dst.numel()
    if n == 0:
        return
    src_arg, dst_arg, dst_dt, dst_bool = _pair_args(dst, src)
    if n == src.numel() and src_arg.is_contiguous() and dst_arg.is_contiguous():
        _launch_flat(src_arg, dst_arg, n, dst_dt, dst_bool)
        return
    if _launch_strided(src_arg, dst_arg, dst, src, dst_dt, dst_bool):
        return
    # Exotic rank: peel the outermost destination dimension and recurse.
    align = dst.dim() - src.dim()
    sub_src = src if (align > 0 or src.shape[0] == 1) else src[0]
    for i in range(dst.shape[0]):
        _copy_pair(dst[i], sub_src)


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------


def foreach_copy(self, src, non_blocking=False):
    del non_blocking
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if not isinstance(src, (list, tuple)):
        raise TypeError("argument 'src' must be tuple of Tensors")
    if len(self) != len(src):
        raise RuntimeError(
            "Tensor list must have same number of elements as tensor list"
        )
    outs = []
    groups = {}
    strided = []
    for dst_ref, src_ref in zip(self, src):
        if not isinstance(dst_ref, torch.Tensor) or not isinstance(
            src_ref, torch.Tensor
        ):
            raise TypeError("argument 'self' must be tuple of Tensors")
        out = torch.empty_like(dst_ref)
        outs.append(out)
        n = out.numel()
        if n == 0:
            continue
        if n == src_ref.numel() and src_ref.is_contiguous() and out.is_contiguous():
            src_arg, dst_arg, dst_dt, dst_bool = _pair_args(out, src_ref)
            key = (src_arg.dtype, dst_arg.dtype, dst_bool)
            bucket = groups.get(key)
            if bucket is None:
                bucket = groups[key] = []
            bucket.append((src_arg, dst_arg, n, dst_dt))
        else:
            strided.append((out, src_ref))

    for (_, _, dst_bool), items in groups.items():
        dst_dt = items[0][3]
        if len(items) == 1 or _group_bytes(items) > _FUSE_MAX_BYTES:
            for src_arg, dst_arg, n, _ in items:
                _launch_flat(src_arg, dst_arg, n, dst_dt, dst_bool)
            continue
        for start in range(0, len(items), _MAX_FUSED):
            chunk = items[start : start + _MAX_FUSED]
            if len(chunk) == 1:
                src_arg, dst_arg, n, _ = chunk[0]
                _launch_flat(src_arg, dst_arg, n, dst_dt, dst_bool)
            else:
                _launch_batch(chunk, dst_dt, dst_bool)

    for out, src_ref in strided:
        _copy_pair(out, src_ref)
    return outs
